# Look at zeros adjacent to any 3 (raw BFS, seed = zero with >=k threes neighbors), k from 0..2, spread by all-8.
def rule(I,k=1):
    H,W=len(I),len(I[0])
    O=[r[:] for r in I]
    Z={(i,j) for i in range(H) for j in range(W) if I[i][j]==0}
    T={(i,j) for i in range(H) for j in range(W) if I[i][j]==3}
    def nb(p): return [(p[0]+a,p[1]+b) for a,b in D if 0<=p[0]+a<H and 0<=p[1]+b<W]
    S={z for z in Z if sum(1 for q in nb(z) if q in T)>=k}
    # flood from S over zeros only (can't cross other colors? try both: zeros-only)
    changed=S
    stack=list(S)
    while stack:
        p=stack.pop()
        for q in nb(p):
            if q not in changed:
                changed.add(q)
                stack.append(q)
    for p in changed: O[p[0]][p[1]]=1
    return O
