from collections import defaultdict
def feats(I,O):
    H,W=len(I),len(I[0])
    Z={(i,j) for i in range(H) for j in range(W) if I[i][j]==0}
    def d(p,q): return abs(p[0]-q[0])+abs(p[1]-q[1])
    def c2(p):
        s=0
        for a in(-1,0,1):
            for b in(-1,0,1):
                q=(p[0]+a,p[1]+b)
                if 0<=q[0]<H and 0<=q[1]<W:
                    s+= I[q[0]][q[1]]==2
        return s
    res={}
    D8=[(a,b) for a in(-1,0,1) for b in(-1,0,1) if (a,b)!=(0,0)]
    for i,j in Z:
        D3k=[q for q in [(i+a,j+b) for a,b in D8] if 0<=q[0]<H and 0<=q[1]<W]
        c2_=c2((i,j))
        d2=min([d((i,j),q) for q in D3k if I[q[0]][q[1]]==2], default=99)
        d3=min([d((i,j),q) for q in D3k if I[q[0]][q[1]]==3], default=99)
        res[(i,j)]=(c2_,d2,d3,O[i][j])
    return res
